fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since the array has at least one element,
    // we only need to check adjacent pairs to ensure nondecreasing order.
    for i in 1..arr.len() {
        if arr[i] < arr[i - 1] {
            return false;
        }
    }
    true
}